#!/usr/bin/env python3
"""Render member-specific handoff from retained receipts; no compiler launches."""
from pathlib import Path
import json,collections,lzma,re,subprocess
E=Path(__file__).resolve().parent
def load(p):return json.loads(lzma.decompress(p.read_bytes()) if p.suffix=='.xz' else p.read_bytes())
def main():
 p=load(E/'NMH_PROVENANCE.json');plan=load(E/'NMH_PLAN.json');runs=[]
 for r in plan['runs']:
  a=r['run'];q=E/a/'receipt.json'
  if not q.exists():continue
  rc=load(q);pins=E/(a+'_emitted')/'NHR_PINS.json';pins=load(pins) if pins.exists() else {};tools={}
  for tool in ['charon','aeneas']:
   f=E/(a+'_emitted')/(tool+'_receipt.json')
   if f.exists():
    v=load(f);t=E/(a+'_emitted')/(tool+'.time');raw=t.read_text() if t.exists() else '';rss=re.search(r'Maximum resident set size \(kbytes\): (\d+)',raw);swaps=re.search(r'Swaps: (\d+)',raw);tools[tool]=dict(command=v['command'],exit=v['exit'],wall_seconds=v['wall_seconds'],peak_rss_kib=int(rss[1]) if rss else None,swaps=int(swaps[1]) if swaps else None,tool_sha256=v['tool_sha256'])
  runs.append(dict(attempt=a,groups=r['groups'],roots=r['configuration']['roots'],exit=rc['exit_status'],wall_seconds=rc['wall_seconds'],peak_rss_kib=rc['peak_rss_kib'],cgroup_memory_peak_bytes=rc.get('cgroup_memory_peak_bytes'),swaps=rc['swaps'],source_revision=rc['source_revision'],frozen_revision=rc['frozen_revision'],print_axioms='not applicable: no Lean theorem/compile',tool_results=tools,retired_timeout=rc['exit_status']==124,lock_before=pins.get('lock_before'),lock_after=pins.get('lock_after'),receipt=a+'/receipt.json'))
 (E/'NMH_RUN_SUMMARY.json').write_text(json.dumps(runs,indent=2)+'\n')
 done=len(runs);counts=p['counts'];budget=p['budget_used'];pending=[r for r in p['blobs'] if r['verdict']!='REPRODUCED'];reasons=collections.Counter(r['reason'] for r in pending)
 remaining=['# NMH remaining obligations','', 'Target not yet established. No ledger or trust item changed.','',f"Completed scopes: {done}/30. Tool charges: {budget}. No Lean scope is justified solely to repair missing tool/source provenance; object compilation is reserved for a reproduced module needing an object-hash comparison.",'','## Member-by-member status','', '| Blob | Group | Verdict | Exact remaining obligation |','|---|---|---|---|']
 for r in pending:remaining.append('| '+r['blob']+' | '+r['group']+' | '+r['verdict']+' | '+r['reason'].replace('|','/')+' |')
 remaining+=['','DIFFERS entries require review of their compressed diff and archived transformation chain. NOT_REPRODUCED entries require the stated source/configuration or a successful changed/split tool shape. Missing historical drivers are not inserted into frozen source. Each affected CLOSED row and checked reaching root is retained in NMH_PROVENANCE.json and NMH_ROW_IMPACT.json.xz; no status is changed here.','', 'The 19 diagnostic probes are explicitly partial native-definition projections. Their successes cannot recover omitted reference crates or permit arbitrary namespace/carrier/body normalization. A no-match result is not proof that a selected object lacks a dependency.']
 if budget['Charon']>=30:remaining+=['','Charon allowance is exhausted. Remaining Aeneas allowance cannot generate missing LLBC for an unattempted crate/function set. Lean cannot reconstruct extraction provenance; Kani allowance is zero. All remaining members above identify the source/configuration or failed extraction they require.']
 elif done<24:remaining+=['','This is an intermediate handoff; extraction is continuing. It is not an early-stop claim.']
 (E/'NMH_REMAINING.md').write_text('\n'.join(remaining)+'\n')
 failures=[r['attempt'] for r in runs if r['exit']!=0];peak=max((int(r['peak_rss_kib'] or 0) for r in runs),default=0);wall=sum(r['wall_seconds'] for r in runs)
 summary=f'''\n## Reproduction status from retained receipts\n\n{done} serial scopes completed; verdict counts {counts}. Charged tools: {budget}. Total scoped wall {wall:.3f}s; maximum reported process RSS {peak} KiB. Full per-tool GNU time results and cgroup peaks are in NMH_RUN_SUMMARY.json and original receipts. Failed scopes: {', '.join(failures) or 'none'}. An incomplete killed-tool receipt is null, never inferred successful.\n\nA REPRODUCED verdict is limited to exact committed bytes or the named NHR discriminant-metadata adaptation. DIFFERS is a byte/configuration result, not a semantic counterexample. NMH_DEFINITION_COMPARISONS.json.xz retains exact NKT-style declaration segment hashes for every member and candidate output. No new normalization is used.\n'''
 reproduced=[r for r in p['blobs'] if r['verdict']=='REPRODUCED']
 for r in reproduced:summary+=f"\nReproduced member `{r['blob']}`: `{r['committed_paths'][0]}`, run `{r['run']}`, normalization `{r['normalization'] or 'none'}`. Raw output SHA `{r['reproduced_hash']}`; normalized SHA `{r.get('normalized_hash') or r['reproduced_hash']}`. This is blob provenance, not a new function/row/security proof.\n"
 f=E/'NMH_FINDINGS.md';s=f.read_text().split('\n## Reproduction status from retained receipts')[0];f.write_text(s+summary)
 handoff=f'''# NMH extraction provenance handoff\n\n**Target not yet established.** Branch codex/cx-emission-repro-20261107; local commits only, no push. This packet investigates NKT-F2, without a new row proof, ledger edit, trust change or shipped-source change.\n\n{done}/30 serial extraction scopes completed. Verdicts for all 336 requested blobs: {counts}. Tool charges: {budget}; limits Charon30/Aeneas30/Lean10/Kani0. See NMH_PROVENANCE.json for each blob's committed/reproduced hashes, run, verdict, reason and affected CLOSED rows. NMH_PLAN.json records packet partitions and one explicit configuration per run. NMH_REMAINING.md records every unresolved member.\n\nFrozen crates, verifier program and Cargo.lock: 4bb3b3f51e16b4525f1d10336e2b0bcbbd775387. Pool: b936275465 (full git revision and per-file git/SHA pins in NMH_STAGING_MANIFEST.json). NMH_NHR_stage.py is unchanged NHR_stage.py; NMH_extract.py supplies archived options or explicitly labelled diagnostic selectors through its API. All original source/lock/graph/tool checks remain. NMH_CLIENT_CHANGES.md records the owned controller adaptations. No shared launcher, reservation, shim, workspace or sibling worktree changed.\n\nEvery launched scope has reservation exit0 and allowed:true, a >=40GB free-disk check, and 6G high/8G max/swap0/64-task limits. One scope at a time; optimized release Rust; timeout180 unchanged. NMH_ATTEMPTS.jsonl, NMH_TOOL_ATTEMPTS.jsonl and per-run receipts record exact commands, pins, source revision, exits, wall, RSS, swaps and cgroup peaks. No failed/timed-out shape is rerun unchanged. Own host writes remain limited to the assigned workspace and below30GB.\n\nAll 1,081 distinct ledger24 CLOSED roots have archived reachability lists; NMH_ROW_IMPACT.json.xz pins each list and intersects fully qualified declarations. Historical aliases defining the same constant remain conservative source-to-object candidates. This is not a replacement for NKT's missing selected-source/object mapping. The batch_tree family is cross-referenced to NKT-F1/(bc). NKT-F3 remains explicit: TX1:059/TX2:040 have no named roots, so their emission impact is unassessed, never asserted absent. The lead decides row consequences; no row or trust item is reopened or edited here.\n\nNo new theorem or Lean compile: #print axioms is not applicable. Raw Aeneas external templates are uncompiled evidence, never new trusted axioms. No hypothesis, runtime/cryptographic assumption, metric, carrier, privacy requirement or two-transaction requirement is added, discharged or changed. Headline remains AspisR1.RPx_Deployed.deployed with L154 parameter and narrowed D188.\n\nNo shipped-file or cfg(kani) change, so no ELF rebuild trigger. Inherited only: default f8c0ec72621fd5029a97d796c4a3623d0dc44a8e7074122372f9872915d143d4; devnet63ad3e9cc096dcbb55b3ca7ac7c8e89e6a845796ab5e4f5b7d15db96f3784299; Pool121f3e29741f510e6dc42d0345fc3c36217600f0be337094855c4a9da2581548. No key/wallet operation occurred.\n\nValidation: NMH_tests.py parser/comparator controls; NMH_validate.py checks full336 coverage, admitted/capped receipts, retained output hashes, tool budgets, unchanged ledger/shipped inputs and20MB hygiene. Its result is PASS_WITH_PROVENANCE_GAPS, never a universal fidelity or100-bit security pass.\n'''
 (E/'NMH_HANDOFF.md').write_text(handoff)
 if (E/'NMH_HOST_CLEANUP.json').exists():
  host=load(E/'NMH_HOST_POSTCHECK.json');cleanup=load(E/'NMH_HOST_CLEANUP.json');nllbc=len(list(E.glob('NMH_E*_emitted/*.llbc.xz')))
  finalinfo=f"\n## Final recovery and exclusions\n\nAll {nllbc} completed LLBC inputs are retained compressed with SHA256 sidecars. Final recovery records no source/lock drift and no active owned process. Owned workspace before cleanup: {host['owned_bytes']:,} bytes. Only rebuildable Cargo output was removed: {cleanup['removed_bytes']:,} bytes; persistent Lean cache untouched. Remaining owned workspace: {cleanup['remaining_owned_bytes']:,} bytes; host free disk: {cleanup['free_bytes']:,} bytes.\n\nE002 interrupted NHR's final lock check and has no completed LLBC/Aeneas receipt. Subsequent frozen preflight and final recovery match the lock; the timed-out attempt retains no credit. E006 remains an opacity-input refusal; corrected E030 is separately recorded. NKT-F3 rootless rows TX1:059/TX2:040 remain unassessed, never asserted absent. No ledger or trust change.\n"
  for name in ['NMH_FINDINGS.md','NMH_HANDOFF.md']:
   q=E/name;q.write_text(q.read_text()+finalinfo)
 print(json.dumps(dict(scopes=done,counts=counts,budget=budget,failures=failures)))
if __name__=='__main__':main()
